//! Sine lookup tables, built at compile time.
//!
//! Angles in the integer API are "binary degrees": a full turn is
//! [`ANGLE_FULL`] (1024) units, so wrapping is a single bit mask. The tables
//! are generated by a `const fn` Taylor series, so they cost nothing at
//! startup and live in read-only memory.

use std::f64::consts::PI;

/// Units in one full turn for [`isin`] / [`icos`].
pub const ANGLE_FULL: i32 = 1024;
const MASK: i32 = ANGLE_FULL - 1;

/// `sin` in Q16.16 fixed point (65536 = 1.0), 1024 entries per turn.
pub static SIN_Q16: [i32; ANGLE_FULL as usize] = build_sin_q16();

/// `127.5 + 127.5 * sin`, rounded, 256 entries per turn. The classic plasma
/// table: summing a few of these gives an 8-bit-friendly field.
pub static SIN_U8: [u8; 256] = build_sin_u8();

const fn const_sin(x: f64) -> f64 {
    let two_pi = 2.0 * PI;
    let mut x = x;
    while x > PI {
        x -= two_pi;
    }
    while x < -PI {
        x += two_pi;
    }
    // Taylor series to x^25: below 1e-12 error on [-pi, pi].
    let x2 = x * x;
    let mut term = x;
    let mut sum = x;
    let mut n = 1;
    while n <= 12 {
        let k = (2 * n) as f64;
        term = -term * x2 / (k * (k + 1.0));
        sum += term;
        n += 1;
    }
    sum
}

const fn round(v: f64) -> i32 {
    if v >= 0.0 { (v + 0.5) as i32 } else { (v - 0.5) as i32 }
}

const fn build_sin_q16() -> [i32; ANGLE_FULL as usize] {
    let mut t = [0i32; ANGLE_FULL as usize];
    let mut i = 0;
    while i < ANGLE_FULL as usize {
        t[i] = round(const_sin(i as f64 * 2.0 * PI / ANGLE_FULL as f64) * 65536.0);
        i += 1;
    }
    t
}

const fn build_sin_u8() -> [u8; 256] {
    let mut t = [0u8; 256];
    let mut i = 0;
    while i < 256 {
        t[i] = round(127.5 + 127.5 * const_sin(i as f64 * 2.0 * PI / 256.0)) as u8;
        i += 1;
    }
    t
}

/// Fixed-point sine: `angle` in 1/1024 turns, result in Q16.16.
#[inline]
pub fn isin(angle: i32) -> i32 {
    SIN_Q16[(angle & MASK) as usize]
}

/// Fixed-point cosine: `angle` in 1/1024 turns, result in Q16.16.
#[inline]
pub fn icos(angle: i32) -> i32 {
    SIN_Q16[((angle + ANGLE_FULL / 4) & MASK) as usize]
}

/// Converts radians to the 1/1024-turn integer angle.
#[inline]
pub fn to_angle(radians: f32) -> i32 {
    (radians * (ANGLE_FULL as f32 / std::f32::consts::TAU)) as i32
}

/// Table-driven `sin` for `f32` with linear interpolation (|error| < 5e-6).
#[inline]
pub fn fsin(x: f32) -> f32 {
    let pos = (x * (ANGLE_FULL as f32 / std::f32::consts::TAU)).rem_euclid(ANGLE_FULL as f32);
    let i = pos as i32;
    let frac = pos - i as f32;
    let a = SIN_Q16[(i & MASK) as usize] as f32;
    let b = SIN_Q16[((i + 1) & MASK) as usize] as f32;
    (a + (b - a) * frac) * (1.0 / 65536.0)
}

/// Table-driven `cos` for `f32`.
#[inline]
pub fn fcos(x: f32) -> f32 {
    fsin(x + std::f32::consts::FRAC_PI_2)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn const_sin_matches_std() {
        for i in -2000..2000 {
            let x = i as f64 * 0.01;
            assert!((const_sin(x) - x.sin()).abs() < 1e-9, "x = {x}");
        }
    }

    #[test]
    fn q16_table_landmarks() {
        assert_eq!(isin(0), 0);
        assert_eq!(isin(256), 65536);
        assert_eq!(isin(512), 0);
        assert_eq!(isin(768), -65536);
        assert_eq!(icos(0), 65536);
        assert_eq!(isin(1024 + 256), 65536, "angles wrap");
        assert_eq!(isin(-256), -65536, "negative angles wrap");
    }

    #[test]
    fn u8_table_range() {
        assert_eq!(SIN_U8[0], 128);
        assert_eq!(SIN_U8[64], 255);
        assert_eq!(SIN_U8[192], 0);
    }

    #[test]
    fn fsin_is_accurate() {
        for i in -5000..5000 {
            let x = i as f32 * 0.0037;
            assert!((fsin(x) - x.sin()).abs() < 2e-5, "sin {x}");
            assert!((fcos(x) - x.cos()).abs() < 2e-5, "cos {x}");
        }
    }

    #[test]
    fn to_angle_quarter_turn() {
        assert_eq!(to_angle(std::f32::consts::FRAC_PI_2), 256);
    }
}
